/bin/bash -lc "jshell <<'EOF'
import java.time.YearMonth;
import java.time.format.*;
var f = DateTimeFormatter.ofPattern(\"uuuu-MM\").withResolverStyle(ResolverStyle.STRICT);
YearMonth.parse(\"2026-09\", f);
try { YearMonth.parse(\"2026-13\", f); throw new AssertionError(); } catch (DateTimeParseException expected) { }
try { YearMonth.parse(\"2026-9\", f); throw new AssertionError(); } catch (DateTimeParseException expected) { }
System.out.println(\"period validation passed\");
EOF
